// EWR ground chart data. Generated by scripts/build_chart.py from the backend's
// KEWR taxiway graph + OpenStreetMap runways. Re-run the script when the graph changes.
import chartData from "~/data/kewr-chart.json";
import type { VehicleInfo } from "~/lib/sim-state";

export type Point = [number, number];

export type Runway = {
  id: string;
  lengthFt: number;
  widthPx: number;
  from: Point;
  to: Point;
  ends: { label: string; at: Point; toward: Point }[];
};

export type Taxiway = {
  id: string;
  name: string | null;
  d: string;
  label: Point;
  lengthFt: number;
};

export type ChartNode = {
  id: string;
  name: string;
  x: number;
  y: number;
  kind: "hold" | "crossing" | "exit" | "intersection" | "end";
  holdType: string | null;
  taxiways: string[];
  /** Every taxiway id this node sits on, including unnamed ones. */
  on: string[];
};

// Cast through unknown: the JSON is generated by our own script, and TS infers tuples as number[].
export const chart = chartData as unknown as {
  projection: { zoom: number; originX: number; originY: number; width: number; height: number };
  runways: Runway[];
  taxiways: Taxiway[];
  nodes: ChartNode[];
  /** Every graph node in chart pixels. */
  positions: Record<string, Point>;
  /** Adjacency list from the backend graph. */
  graph: Record<string, string[]>;
  /** Real curve of each edge, keyed "a|b" with a < b. */
  edges: Record<string, Point[]>;
};

export const hasNode = (id: string) => id in chart.positions;

/** The curve between two neighbouring nodes, in travel order. Straight line if unknown. */
export function edgeLine(a: string, b: string): Point[] {
  const forward = chart.edges[`${a}|${b}`];
  if (forward) return forward;
  const backward = chart.edges[`${b}|${a}`];
  if (backward) return [...backward].reverse();
  return [chart.positions[a], chart.positions[b]];
}

/** A route of node ids as one polyline that follows the taxiway curves. */
export function routeLine(route: string[]): Point[] {
  const ids = route.filter(hasNode);
  if (ids.length < 2) return ids.map((id) => chart.positions[id]);
  return ids.slice(1).flatMap((id, i) => {
    const line = edgeLine(ids[i], id);
    return i === 0 ? line : line.slice(1); // shared node appears once
  });
}

export const lineLength = (pts: Point[]) =>
  pts.slice(1).reduce((sum, p, i) => sum + Math.hypot(p[0] - pts[i][0], p[1] - pts[i][1]), 0);

/**
 * Where a vehicle is drawn: `progress` (0 to 1) of the way along the route's total length,
 * following the real taxiway curves. Heading is in degrees clockwise from up (chart north).
 */
export function routePoint(route: string[], progress: number, fallback?: string) {
  const pts = routeLine(route);
  if (pts.length < 2) {
    const p = pts[0] ?? (fallback && hasNode(fallback) ? chart.positions[fallback] : null);
    return p ? { x: p[0], y: p[1], heading: null } : null;
  }
  let remaining = Math.min(Math.max(progress, 0), 1) * lineLength(pts);
  for (let i = 0; i < pts.length - 1; i++) {
    const [ax, ay] = pts[i];
    const [bx, by] = pts[i + 1];
    const len = Math.hypot(bx - ax, by - ay);
    if (remaining <= len || i === pts.length - 2) {
      const t = len ? Math.min(remaining / len, 1) : 0;
      return {
        x: ax + (bx - ax) * t,
        y: ay + (by - ay) * t,
        heading: (Math.atan2(bx - ax, -(by - ay)) * 180) / Math.PI,
      };
    }
    remaining -= len;
  }
  return null;
}

const nodeInfo = new Map(chart.nodes.map((n) => [n.id, n]));

/**
 * "taxiway B" for a node id. Bends in a line have no name, so walk the graph
 * (breadth-first) to the closest node that does. Falls back to the raw id.
 */
export function placeName(id: string) {
  // Runway ends from the backend graph ("rwy_22R") name themselves.
  if (id.startsWith("rwy_")) return `runway ${id.slice(4)}`;
  const seen = new Set([id]);
  let frontier = [id];
  for (let depth = 0; depth < 25 && frontier.length; depth++) {
    for (const node of frontier) {
      const names = nodeInfo.get(node)?.taxiways ?? [];
      const runway = names.find((t) => t.startsWith("RWY "));
      if (runway) return `runway ${runway.slice(4)}`;
      if (names.length) return `taxiway ${names.join("/")}`;
    }
    frontier = frontier.flatMap((n) => chart.graph[n] ?? []).filter((n) => !seen.has(n) && seen.add(n));
  }
  return id;
}

/** lat/lon -> chart pixel, same Web Mercator math as the build script. Use it for vehicles from the backend. */
export function project(lat: number, lon: number): Point {
  const { zoom, originX, originY } = chart.projection;
  const scale = 256 * 2 ** zoom;
  const s = Math.sin((lat * Math.PI) / 180);
  const x = ((lon + 180) / 360) * scale;
  const y = (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * scale;
  return [x - originX, y - originY];
}

export type HoverTarget =
  | { kind: "runway"; item: Runway }
  | { kind: "taxiway"; item: Taxiway }
  | { kind: "node"; item: ChartNode }
  | { kind: "vehicle"; item: VehicleInfo };

const holdReasons: Record<string, string> = {
  runway: "Protects the runway ahead. Planes may not pass without clearance.",
  ILS: "Keeps planes clear of the radio beam that guides landing aircraft.",
  movement: "Marks where the ramp ends and controlled taxiways begin.",
  intermediate: "A waypoint on the taxiway where planes can be told to wait.",
};

/** Plain-English label for whatever the cursor is over. */
export function describe(target: HoverTarget): { eyebrow: string; title: string; body: string } {
  switch (target.kind) {
    case "runway": {
      const r = target.item;
      return {
        eyebrow: "Runway",
        title: r.id,
        body: `Where planes take off and land. ${r.lengthFt.toLocaleString()} ft long. The numbers are its compass heading: ${r.ends[0].label} points about ${parseInt(r.ends[0].label) * 10}°.`,
      };
    }
    case "taxiway": {
      const t = target.item;
      return t.name
        ? {
            eyebrow: "Taxiway",
            title: t.name,
            body: `A road planes drive on between the gates and the runways. About ${t.lengthFt.toLocaleString()} ft of pavement.`,
          }
        : {
            eyebrow: "Taxiway",
            title: "Unnamed connector",
            body: "A short paved link between taxiways with no official letter.",
          };
    }
    case "vehicle": {
      const v = target.item;
      const warning = v.inConflict ? " Conflict: it's on a collision course with another vehicle." : "";
      if (v.kind === "truck") {
        return {
          eyebrow: "Ground vehicle",
          title: v.label,
          body: `An airport vehicle (fire truck, tug or service car) driving on the airfield.${warning}`,
        };
      }
      const where = v.destination ? placeName(v.destination) : "its destination";
      const doing = {
        waiting: "Waiting at its spot for a taxi clearance.",
        taxiing: `Taxiing to ${where}.`,
        holding: "Holding short: stopped at a line, waiting for permission to continue.",
        arrived: `Arrived at ${where}.`,
      }[v.status ?? "waiting"];
      return { eyebrow: "Aircraft", title: v.label, body: doing + warning };
    }
    case "node": {
      const n = target.item;
      const where = n.taxiways.length ? `on ${n.taxiways.join(" / ")}` : "";
      if (n.kind === "hold") {
        return {
          eyebrow: "Hold-short point",
          title: where ? `Stop line ${where}` : "Stop line",
          body: holdReasons[n.holdType ?? ""] ?? "A painted stop line. Planes wait here until cleared.",
        };
      }
      if (n.kind === "crossing") {
        const runway = n.taxiways.find((t) => t.startsWith("RWY"))?.replace("RWY ", "") ?? "a runway";
        const taxiway = n.taxiways.find((t) => !t.startsWith("RWY"));
        return {
          eyebrow: "Runway crossing",
          title: n.name,
          body: `Where ${taxiway ? `taxiway ${taxiway}` : "a taxiway"} crosses runway ${runway}. Planes and vehicles need explicit permission to cross. This is where runway incursions happen.`,
        };
      }
      if (n.kind === "exit") {
        return {
          eyebrow: "Runway exit",
          title: n.name,
          body: "Where landing planes turn off the runway onto a taxiway.",
        };
      }
      if (n.kind === "intersection") {
        return {
          eyebrow: "Intersection",
          title: n.taxiways.join(" / ") || "Connector junction",
          body: "Where taxiways meet. Routes turn here.",
        };
      }
      return {
        eyebrow: "Taxiway end",
        title: n.taxiways.join(" / ") || "Dead end",
        body: "The end of a taxiway, usually where it meets a gate area or ramp.",
      };
    }
  }
}
